func (r *Runtime) Current() Snapshot {
	if r == nil {
		return Snapshot{Reason: "unavailable"}
	}
	if snapshot := r.snapshot.Load(); snapshot != nil {
		if r.checkClock() != nil {
			blocked := *snapshot
			blocked.Ready, blocked.Leader, blocked.Reason = false, false, "clock-unhealthy"
			return blocked
		}
		return *snapshot
	}
	return Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Reason: "not-observed"}
}

