func NextRoster(current Roster, home string, seen map[string]Heartbeat, now time.Time) (Roster, bool) {
	var regions []RosterEntry
	homeEntry := RosterEntry{Cell: home, State: RegionActive}
	if index := slices.IndexFunc(current.Regions, func(entry RosterEntry) bool { return entry.Cell == home }); index >= 0 {
		homeEntry.OCIRegion = current.Regions[index].OCIRegion
	}
	for cell, heartbeat := range seen {
		if cell == home {
			homeEntry.OCIRegion = heartbeat.OCIRegion
		} else if now.Sub(heartbeat.SentAt) < RegionSilence {
			regions = append(regions, RosterEntry{Cell: cell, OCIRegion: heartbeat.OCIRegion, State: RegionActive})
		}
	}
	regions = append(regions, homeEntry)
	slices.SortFunc(regions, func(a, b RosterEntry) int { return strings.Compare(a.Cell, b.Cell) })
	if current.HomeRegion == home && slices.Equal(regions, current.Regions) {
		return current, false
	}
	return Roster{Generation: current.Generation + 1, HomeRegion: home, Regions: regions}, true
}

internal/globalcontrol/store.go::OpenHom.text:
func OpenHome(ctx context.Context, js jetstream.JetStream, cell string, peers []string, replicas int,
	fencer authority.Fencer,
) (*Writer, error) {
	if !cellToken.MatchString(cell) {
		return nil, errors.New("global home cell is invalid")
	}
	if err := validMirrorPeers(cell, peers); err != nil {
		return nil, err
	}
	if fencer == nil || fencer.Current().Scope != protocol.GlobalScope {
		return nil, errors.New("global writes require the global-scope authority")
	}
	stream, err := openStream(ctx, js, HomeStreamConfig(replicas), func(actual jetstream.StreamConfig) error {
		return verifyHome(actual, replicas)
	})
	if err != nil {
		return nil, err
	}
	if err := ensureMirrorConsumers(ctx, stream, peers, replicas); err != nil {
		return nil, err
	}
	if err := removeStaleMirrorConsumers(ctx, stream, peers); err != nil {
		return nil, err
	}
	return &Writer{Reader: Reader{stream: stream, js: js}, home: cell, fencer: fencer, replicas: replicas}, nil
}

