internal/globalview/drilldown.go::drilld.text:
func drilldownData(rollup *Rollup, resource string, request *http.Request) (any, bool) {
	switch resource {
	case "services":
		return slices.Clone(rollup.Services), true
	case "services/{service}":
		if index := slices.IndexFunc(rollup.Services, func(service swarmruntime.ServiceObservation) bool {
			return service.ServiceID == request.PathValue("service")
		}); index >= 0 {
			return rollup.Services[index], true
		}
	case "nodes":
		return append([]Node{}, rollup.Nodes...), true
	case "volumes":
		return append([]Volume{}, rollup.Volumes...), true
	case "volumes/{volume}":
		if index := slices.IndexFunc(rollup.Volumes, func(volume Volume) bool { return volume.ID == request.PathValue("volume") }); index >= 0 {
			return rollup.Volumes[index], true
		}
	default:
		index := slices.IndexFunc(rollup.Nodes, func(node Node) bool { return node.Name == request.PathValue("node") })
		if index < 0 {
			return nil, false
		}
		node := rollup.Nodes[index]
		switch resource {
		case "nodes/{node}":
			return node, true
		case "nodes/{node}/services":
			return append([]Service{}, node.Services...), true
		case "nodes/{node}/services/{service}":
			if index := slices.IndexFunc(node.Services, func(service Service) bool { return service.Role == request.PathValue("service") }); index >= 0 {
				return node.Services[index], true
			}
		}
	}
	return nil, false
}

internal/globalview/drilldown.go::mountD.text:
func mountDrilldowns(mux *http.ServeMux, view *View) {
	for _, resource := range []string{"nodes", "nodes/{node}", "nodes/{node}/services", "nodes/{node}/services/{service}", "volumes", "volumes/{volume}", "services", "services/{service}"} {
		mux.HandleFunc("GET /v1/regions/{region}/"+resource, func(writer http.ResponseWriter, request *http.Request) {
			region, listed := view.Region(request.PathValue("region"))
			result := ResourceView{Version: 1, Cell: region.Cell, State: "not_found"}
			if !listed {
				writeResource(writer, result, http.StatusNotFound)
				return
			}
			if region.Rollup == nil {
				result.State = "missing"
				writeResource(writer, result, http.StatusServiceUnavailable)
				return
			}
			result.ObservedAt, result.Truncated = region.Rollup.ObservedAt, region.Rollup.Truncated
			data, found := drilldownData(region.Rollup, resource, request)
			result.State, result.Data = region.ResourceState(found), data
			if resource == "services" || resource == "services/{service}" {
				observed := region.Rollup.ServicesObservedAt
				for _, service := range region.Rollup.Services {
					if resource == "services" || service.ServiceID == request.PathValue("service") {
						if service.ObservedAt.IsZero() || service.ObservedAt.Before(observed) {
							observed = service.ObservedAt
						}
					}
				}
				result.State = region.ManagedServiceState(found, observed)
				result.ObservedAt = observed
				if result.State == "unavailable" {
					result.Data, found = nil, false
				}
			}
			if (resource == "volumes" || resource == "volumes/{volume}") && region.Rollup.VolumesUnavailable {
				result.State, result.Data = "unavailable", nil
				found = false
			}
			status := http.StatusOK
			if !found {
				status = http.StatusServiceUnavailable
				if result.State == "not_found" {
					status = http.StatusNotFound
				}
			}
			writeResource(writer, result, status)
		})
	}
}

internal/globalview/function_http.go::mo.text:
func mountFunctionViews(mux *http.ServeMux, view *View) {
	for _, path := range []string{"functions", "functions/{tenant}/{function}"} {
		mux.HandleFunc("GET /v1/regions/{region}/"+path, func(w http.ResponseWriter, r *http.Request) {
			region, listed := view.Region(r.PathValue("region"))
			result := ResourceView{Version: 1, Cell: region.Cell, State: "not_found"}
			found := false
			if listed && region.Rollup != nil {
				result.Truncated, result.ObservedAt = region.Rollup.Truncated, region.Rollup.FunctionsObservedAt
				if path == "functions" {
					found, result.Data = true, slices.Clone(region.Rollup.Functions)
					result.State = region.FunctionState(nil, true)
					for _, function := range region.Rollup.Functions {
						if state := region.FunctionState(&function, true); state != "current" {
							result.State = state
							break
						}
					}
				} else {
					var functions []FunctionObservation
					for _, function := range region.Rollup.Functions {
						if function.TenantID == r.PathValue("tenant") && function.FunctionID == r.PathValue("function") {
							functions = append(functions, function)
						}
					}
					found = len(functions) > 0
					result.State = region.FunctionState(nil, found)
					if found {
						result.Data = functions
						for _, function := range functions {
							if state := region.FunctionState(&function, true); state != "current" {
								result.State = state
							}
							if function.ObservedAt.Before(result.ObservedAt) {
								result.ObservedAt = function.ObservedAt
							}
						}
					}
				}
			} else if listed {
				result.State = "missing"
			}
			status := http.StatusOK
			if !found || result.State == "unavailable" && result.Data == nil {
				status = http.StatusServiceUnavailable
				if result.State == "not_found" {
					status = http.StatusNotFound
				}
			}
			writeResource(w, result, status)
		})
	}
}

internal/globalview/functions.go::Region.text:
func (region Region) FunctionState(observation *FunctionObservation, found bool) string {
	if region.Rollup != nil && region.Rollup.FunctionsObservedAt.IsZero() {
		return "unavailable"
	}
	state := region.ResourceState(found)
	if state != "current" && state != "not_found" {
		return state
	}
	observed := region.Rollup.FunctionsObservedAt
	if observation != nil {
		if observation.State != "observed" && observation.State != "unplaced" || observation.State == "observed" && observation.Snapshot == nil {
			return "unavailable"
		}
		observed = observation.ObservedAt
	}
	if observed.IsZero() || region.Rollup.ObservedAt.Sub(observed) > StaleAfter {
		return "stale"
	}
	return state
}

internal/globalview/http.go::Handler.text:
func Handler(view *View) http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /v1/regions", func(writer http.ResponseWriter, request *http.Request) {
		writeJSON(writer, view.Regions())
	})
	mux.HandleFunc("GET /v1/regions/{region}", func(writer http.ResponseWriter, request *http.Request) {
		region, ok := view.Region(request.PathValue("region"))
		if !ok {
			http.Error(writer, "region is not configured", http.StatusNotFound)
			return
		}
		writeJSON(writer, region)
	})
	mountDrilldowns(mux, view)
	mountFunctionViews(mux, view)
	return mux
}

internal/globalview/http.go::writeJSON.text:
func writeJSON(writer http.ResponseWriter, value any) {
	writer.Header().Set("Content-Type", "application/json")
	writer.Header().Set("Cache-Control", "no-store")
	writer.Header().Set("X-Content-Type-Options", "nosniff")
	_ = json.NewEncoder(writer).Encode(value)
}

internal/globalview/managed_services.go:.text:
func (region Region) ManagedServiceState(found bool, observed time.Time) string {
	if region.Rollup != nil && region.Rollup.ServicesObservedAt.IsZero() {
		return "unavailable"
	}
	state := region.ResourceState(found)
	if state != "current" && state != "not_found" {
		return state
	}
	if observed.IsZero() || region.Rollup.ObservedAt.Sub(observed) > StaleAfter {
		return "stale"
	}
	return state
}

func boundedManagedServices(source []swarmruntime.ServiceObservation, truncated *bool) []swarmruntime.ServiceObservation {
	services := slices.Clone(source)
	slices.SortFunc(services, func(a, b swarmruntime.ServiceObservation) int { return strings.Compare(a.ServiceID, b.ServiceID) })
	services = keep(services, 32, truncated)
	var bytes int
	var result []swarmruntime.ServiceObservation
	for _, service := range services {
		service.Tasks = keep(slices.Clone(service.Tasks), 16, truncated)
		data, err := json.Marshal(service)
		if err != nil || bytes+len(data) > 64<<10 {
			*truncated = true
			continue
		}
		bytes += len(data)
		result = append(result, service)
	}
	return result
}

internal/globalview/publish.go::Publish.text:
func Publish(ctx context.Context, conn *nats.Conn, cell string, leading func() bool, build func(context.Context) Rollup, view *View) {
	ticker := time.NewTicker(PublishEvery)
	defer ticker.Stop()
	for {
		if leading() {
			publishOnce(ctx, conn, cell, build, view)
		}
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
	}
}

internal/globalview/publish.go::publishO.text:
func publishOnce(ctx context.Context, conn *nats.Conn, cell string, build func(context.Context) Rollup, view *View) {
	buildCtx, cancel := context.WithTimeout(ctx, PublishEvery)
	defer cancel()
	r := build(buildCtx)
	data, err := json.Marshal(r)
	if err != nil {
		slog.Warn("dashboard rollup not encoded", observability.ComponentKey, "globalview", "cell", cell, "error", err)
		return
	}
	if len(data) > MaxBytes {
		slog.Warn("dashboard rollup too large, not published", observability.ComponentKey, "globalview", "cell", cell, "bytes", len(data))
		return
	}
	if err := conn.Publish(protocol.RegionRollupSubject(cell), data); err != nil {
		slog.Warn("dashboard rollup not published", observability.ComponentKey, "globalview", "cell", cell, "error", err)
	}
	view.Accept(r)
}

internal/globalview/view.go::NewView.text:
func NewView(local string, regions func() []string, now func() time.Time) *View {
	if now == nil {
		now = time.Now
	}
	return &View{
		local:       normalize(local),
		regions:     regions,
		now:         now,
		rollups:     map[string]*Rollup{},
		persisted:   map[string]time.Time{},
		persistedAt: map[string]time.Time{},
		changed:     make(chan struct{}),
	}
}

internal/globalview/view.go::OpenBucket.text:
func OpenBucket(ctx context.Context, js jetstream.JetStream, replicas int) (jetstream.KeyValue, error) {
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket:       Bucket,
		Description:  "TS-805 last-known dashboard rollup per region",
		History:      1,
		Replicas:     max(replicas, 1),
		Storage:      jetstream.FileStorage,
		MaxValueSize: MaxBytes,
	})
	if err != nil {
		return nil, fmt.Errorf("open %s bucket: %w", Bucket, err)
	}
	return kv, nil
}

internal/globalview/view.go::View.Accept.text:
func (v *View) Accept(r Rollup) bool {
	v.mu.Lock()
	defer v.mu.Unlock()
	if validate(r, v.now()) != nil {
		return false
	}
	held := v.rollups[r.Cell]
	if held != nil && !r.ObservedAt.After(held.ObservedAt) {
		return false
	}
	if held == nil && len(v.rollups) >= maxRegions {
		v.prune()
		if len(v.rollups) >= maxRegions {
			return false
		}
	}
	v.rollups[r.Cell] = &r
	close(v.changed)
	v.changed = make(chan struct{})
	return true
}

internal/globalview/view.go::View.Change.text:
func (v *View) Changed() <-chan struct{} {
	v.mu.Lock()
	defer v.mu.Unlock()
	return v.changed
}

internal/globalview/view.go::View.Follow.text:
func (v *View) Follow(ctx context.Context, conn *nats.Conn) error {
	sub, err := conn.Subscribe(protocol.RegionRollupGrant, func(msg *nats.Msg) {
		r, err := decode(msg.Subject, msg.Data)
		if err != nil {
			slog.Debug("dashboard rollup dropped", observability.ComponentKey, "globalview", "error", err)
			return
		}
		v.Accept(r)
	})
	if err != nil {
		return fmt.Errorf("subscribe region rollups: %w", err)
	}
	<-ctx.Done()
	if err := sub.Unsubscribe(); err != nil {
		slog.Debug("dashboard rollup subscription not closed", observability.ComponentKey, "globalview", "error", err)
	}
	return nil
}

internal/globalview/view.go::View.KeepLa.text:
func (v *View) KeepLastKnown(ctx context.Context, kv jetstream.KeyValue, leading func() bool) {
	if err := v.load(ctx, kv); err != nil {
		slog.Warn("dashboard last-known rollups not loaded", observability.ComponentKey, "globalview", "error", err)
	}
	ticker := time.NewTicker(PersistEvery)
	defer ticker.Stop()
	for {
		if leading() {
			persistCtx, cancel := context.WithTimeout(ctx, PersistEvery)
			if err := v.Persist(persistCtx, kv); err != nil {
				slog.Warn("dashboard rollups not persisted", observability.ComponentKey, "globalview", "error", err)
			}
			cancel()
		}
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
	}
}

internal/globalview/view.go::View.Persis.text:
func (v *View) Persist(ctx context.Context, kv jetstream.KeyValue) error {
	type write struct {
		cell   string
		rollup *Rollup
	}
	v.mu.Lock()
	cells := v.listed()
	var writes []write
	for _, cell := range cells {
		r := v.rollups[cell]
		if r == nil || !r.ObservedAt.After(v.persisted[cell]) || v.now().Sub(v.persistedAt[cell]) < PersistEvery {
			continue
		}
		writes = append(writes, write{cell, r})
	}
	v.mu.Unlock()

	var firstErr error
	keep := func(err error) {
		if firstErr == nil {
			firstErr = err
		}
	}
	for _, w := range writes {
		data, err := json.Marshal(w.rollup)
		if err != nil {
			keep(fmt.Errorf("encode rollup %s: %w", w.cell, err))
			continue
		}
		if _, err := kv.Put(ctx, w.cell, data); err != nil {
			keep(fmt.Errorf("persist rollup %s: %w", w.cell, err))
			continue
		}
		v.markPersisted(w.cell, w.rollup.ObservedAt)
	}

	// Until the registry lists another region, an unlisted key may only
	// mean the roster is not read yet; deleting it would lose last-known data.
	if len(cells) < 2 {
		return firstErr
	}
	keys, err := kv.Keys(ctx)
	if err != nil && !errors.Is(err, jetstream.ErrNoKeysFound) {
		keep(fmt.Errorf("list rollup keys: %w", err))
		return firstErr
	}
	for _, key := range keys {
		if slices.Contains(cells, key) {
			continue
		}
		if err := kv.Delete(ctx, key); err != nil {
			keep(fmt.Errorf("delete rollup %s: %w", key, err))
		}
	}
	return firstErr
}

internal/globalview/view.go::View.Region.text:
func (v *View) Region(cell string) (Region, bool) {
	v.mu.Lock()
	defer v.mu.Unlock()
	cell = normalize(cell)
	if !slices.Contains(v.listed(), cell) {
		return Region{}, false
	}
	return v.region(cell), true
}

func (v *View) Regions() []Region {
	v.mu.Lock()
	defer v.mu.Unlock()
	cells := v.listed()
	out := make([]Region, 0, len(cells))
	for _, cell := range cells {
		out = append(out, v.region(cell))
	}
	return out
}

internal/globalview/view.go::View.listed.text:
func (v *View) listed() []string {
	var others []string
	if v.regions != nil {
		for _, raw := range v.regions() {
			cell := normalize(raw)
			if cell == "" || cell == v.local || slices.Contains(others, cell) {
				continue
			}
			others = append(others, cell)
		}
	}
	slices.Sort(others)
	if v.local == "" {
		return others
	}
	return append([]string{v.local}, others...)
}

internal/globalview/view.go::View.load.text:
func (v *View) load(ctx context.Context, kv jetstream.KeyValue) error {
	keys, err := kv.Keys(ctx)
	if errors.Is(err, jetstream.ErrNoKeysFound) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("list rollup keys: %w", err)
	}
	for _, key := range keys {
		entry, err := kv.Get(ctx, key)
		if err != nil {
			slog.Warn("dashboard rollup not loaded", observability.ComponentKey, "globalview", "cell", key, "error", err)
			continue
		}
		r, err := decode(protocol.RegionRollupSubject(key), entry.Value())
		if err != nil {
			slog.Debug("dashboard rollup dropped", observability.ComponentKey, "globalview", "cell", key, "error", err)
			continue
		}
		v.Accept(r)
	}
	return nil
}

internal/globalview/view.go::View.markPe.text:
func (v *View) markPersisted(cell string, observed time.Time) {
	v.mu.Lock()
	defer v.mu.Unlock()
	v.persisted[cell] = observed
	v.persistedAt[cell] = v.now()
}

internal/globalview/view.go::View.prune.text:
func (v *View) prune() {
	listed := v.listed()
	for cell := range v.rollups {
		if slices.Contains(listed, cell) {
			continue
		}
		delete(v.rollups, cell)
		delete(v.persisted, cell)
		delete(v.persistedAt, cell)
	}
}

internal/globalview/view.go::View.region.text:
func (v *View) region(cell string) Region {
	r := v.rollups[cell]
	return Region{
		Cell:   cell,
		Rollup: r,
		Stale:  r != nil && v.now().Sub(r.ObservedAt) > StaleAfter,
	}
}

internal/globalview/view.go::decode.text:
func decode(subject string, data []byte) (Rollup, error) {
	var r Rollup
	if err := protocol.DecodeTolerant(data, &r, MaxBytes); err != nil {
		return Rollup{}, err
	}
	if err := validate(r, time.Now()); err != nil {
		return Rollup{}, err
	}
	if tokens := strings.Split(subject, "."); len(tokens) < 4 || tokens[3] != r.Cell {
		return Rollup{}, fmt.Errorf("rollup subject %q does not name cell %q", subject, r.Cell)
	}
	// A scaling status the region cannot validate, or that speaks for another
	// region, is no status: its spend is then unknown and growth holds.
	if r.Scale != nil && (r.Scale.Validate() != nil || r.Scale.Cell != r.Cell) {
		r.Scale = nil
	}
	return r, nil
}

internal/globalview/view.go::normalize.text:
func normalize(cell string) string {
	token, err := protocol.RegionToken(cell)
	if err != nil {
		return ""
	}
	return token
}

internal/globalview/view.go::validate.text:
func validate(r Rollup, now time.Time) error {
	if r.Version != Version {
		return fmt.Errorf("rollup version %d, want %d", r.Version, Version)
	}
	if token, err := protocol.RegionToken(r.Cell); err != nil || token != r.Cell {
		return fmt.Errorf("rollup cell %q is not a region token", r.Cell)
	}
	if r.ObservedAt.IsZero() || r.ObservedAt.After(now.Add(time.Minute)) {
		return fmt.Errorf("rollup observed_at %s is outside the clock window", r.ObservedAt)
	}
	return nil
}

