func TestViewAccept(t *testing.T) {
	c := &fakeClock{now: start}
	view, conn := followedTestView(t, "gru", func() []string { return []string{"sfo"} }, c.Now)

	ch := view.Changed()
	publishTestRollup(t, conn, rollupAt("SFO", start))
